#!/bin/bash\n\n# Swagger Authentication Helper Script\n# This script demonstrates how to authenticate with the Requirements Management API\n# using the same credentials as the backend.LoadTests\n\nset -e  # Exit on any error\n\necho \"🚀 Requirements Management API Authentication Test\"\necho \"====================================================\"\n\n# Configuration (same as backend.LoadTests)\nIDENTITY_SERVER_URL=\"https://rqmtmgmt.local\"\nCLIENT_ID=\"rqmtmgmt-backend\"\nCLIENT_SECRET=\"backend-secret\"\nSCOPE=\"rqmtmgmt.api\"\nAPI_BASE_URL=\"https://rqmtmgmt.local/api\"\n\necho \"🔧 Configuration:\"\necho \"   Identity Server: $IDENTITY_SERVER_URL\"\necho \"   Client ID: $CLIENT_ID\"\necho \"   Scope: $SCOPE\"\necho \"   API Base URL: $API_BASE_URL\"\necho \"\"\n\n# Step 1: Get access token using client credentials flow\necho \"🔑 Step 1: Requesting access token...\"\nTOKEN_RESPONSE=$(curl -k -s -X POST \"$IDENTITY_SERVER_URL/connect/token\" \\\n  -H \"Content-Type: application/x-www-form-urlencoded\" \\\n  -H \"Accept: application/json\" \\\n  -d \"grant_type=client_credentials&client_id=$CLIENT_ID&client_secret=$CLIENT_SECRET&scope=$SCOPE\")\n\nif [ $? -ne 0 ]; then\n  echo \"❌ Failed to get access token\"\n  exit 1\nfi\n\necho \"📋 Token Response:\"\necho \"$TOKEN_RESPONSE\" | jq .\n\n# Extract access token\nACCESS_TOKEN=$(echo \"$TOKEN_RESPONSE\" | jq -r '.access_token')\n\nif [ \"$ACCESS_TOKEN\" = \"null\" ] || [ -z \"$ACCESS_TOKEN\" ]; then\n  echo \"❌ Failed to extract access token from response\"\n  echo \"Raw response: $TOKEN_RESPONSE\"\n  exit 1\nfi\n\necho \"✅ Access token obtained successfully!\"\necho \"Token (first 20 characters): ${ACCESS_TOKEN:0:20}...\"\necho \"\"\n\n# Step 2: Test the token with a simple API call\necho \"📡 Step 2: Testing API call with Bearer token...\"\necho \"Making GET request to: $API_BASE_URL/Dashboard/statistics\"\n\nAPI_RESPONSE=$(curl -k -s -w \"\\nHTTP_STATUS:%{http_code}\\n\" \\\n  -H \"Authorization: Bearer $ACCESS_TOKEN\" \\\n  -H \"Accept: application/json\" \\\n  -H \"Content-Type: application/json\" \\\n  \"$API_BASE_URL/Dashboard/statistics\")\n\n# Extract HTTP status and response body\nHTTP_STATUS=$(echo \"$API_RESPONSE\" | grep \"HTTP_STATUS:\" | cut -d: -f2)\nRESPONSE_BODY=$(echo \"$API_RESPONSE\" | sed '/HTTP_STATUS:/d')\n\necho \"📊 API Response Status: $HTTP_STATUS\"\n\nif [ \"$HTTP_STATUS\" = \"200\" ]; then\n  echo \"✅ API call successful!\"\n  echo \"📋 Response data:\"\n  echo \"$RESPONSE_BODY\" | jq .\nelse\n  echo \"❌ API call failed with status: $HTTP_STATUS\"\n  echo \"📋 Response body:\"\n  echo \"$RESPONSE_BODY\"\nfi\n\necho \"\"\n\n# Step 3: Test additional endpoints\nif [ \"$HTTP_STATUS\" = \"200\" ]; then\n  echo \"🔍 Step 3: Testing additional endpoints...\"\n  \n  # Test Projects endpoint\n  echo \"   Testing /api/Projects...\"\n  PROJECTS_RESPONSE=$(curl -k -s -w \"%{http_code}\" \\\n    -H \"Authorization: Bearer $ACCESS_TOKEN\" \\\n    -H \"Accept: application/json\" \\\n    \"$API_BASE_URL/Projects\" -o /tmp/projects_response.json)\n  \n  if [ \"$PROJECTS_RESPONSE\" = \"200\" ]; then\n    PROJECT_COUNT=$(cat /tmp/projects_response.json | jq '. | length')\n    echo \"   ✅ Projects endpoint: $PROJECT_COUNT projects found\"\n  else\n    echo \"   ❌ Projects endpoint failed with status: $PROJECTS_RESPONSE\"\n  fi\n  \n  # Test Requirements endpoint  \n  echo \"   Testing /api/Requirement...\"\n  REQ_RESPONSE=$(curl -k -s -w \"%{http_code}\" \\\n    -H \"Authorization: Bearer $ACCESS_TOKEN\" \\\n    -H \"Accept: application/json\" \\\n    \"$API_BASE_URL/Requirement\" -o /tmp/requirements_response.json)\n  \n  if [ \"$REQ_RESPONSE\" = \"200\" ]; then\n    REQ_COUNT=$(cat /tmp/requirements_response.json | jq '. | length')\n    echo \"   ✅ Requirements endpoint: $REQ_COUNT requirements found\"\n  else\n    echo \"   ❌ Requirements endpoint failed with status: $REQ_RESPONSE\"\n  fi\n  \n  # Test TestSuites endpoint\n  echo \"   Testing /api/TestSuite...\"\n  SUITE_RESPONSE=$(curl -k -s -w \"%{http_code}\" \\\n    -H \"Authorization: Bearer $ACCESS_TOKEN\" \\\n    -H \"Accept: application/json\" \\\n    \"$API_BASE_URL/TestSuite\" -o /tmp/testsuites_response.json)\n  \n  if [ \"$SUITE_RESPONSE\" = \"200\" ]; then\n    SUITE_COUNT=$(cat /tmp/testsuites_response.json | jq '. | length')\n    echo \"   ✅ TestSuite endpoint: $SUITE_COUNT test suites found\"\n  else\n    echo \"   ❌ TestSuite endpoint failed with status: $SUITE_RESPONSE\"\n  fi\n  \n  # Cleanup temp files\n  rm -f /tmp/projects_response.json /tmp/requirements_response.json /tmp/testsuites_response.json\nfi\n\necho \"\"\necho \"🎯 Summary:\"\necho \"   Token obtained: ✅\"\nif [ \"$HTTP_STATUS\" = \"200\" ]; then\n  echo \"   API call: ✅\"\nelse\n  echo \"   API call: ❌\"\nfi\n\necho \"\"\necho \"📝 Manual curl command for future use:\"\necho \"curl -k -H \\\"Authorization: Bearer $ACCESS_TOKEN\\\" \\\\\"\necho \"     -H \\\"Accept: application/json\\\" \\\\\"\necho \"     \\\"$API_BASE_URL/Dashboard/statistics\\\"\"\n\necho \"\"\necho \"🌐 Swagger UI URL: https://rqmtmgmt.local/swagger/index.html\"\necho \"   Note: Swagger uses a different OAuth2 flow (Authorization Code) with client 'swagger-ui'\"\necho \"   The token above won't work directly in Swagger UI, but the API endpoints will work.\"\n\necho \"\"\necho \"🔧 Debugging Commands:\"\necho \"# Check IdentityServer discovery:\"\necho \"curl -k \\\"https://rqmtmgmt.local/.well-known/openid_configuration\\\" | jq .\"\necho \"\"\necho \"# Decode JWT token payload:\"\necho \"echo \\\"$ACCESS_TOKEN\\\" | cut -d. -f2 | base64 -d | jq .\"\necho \"\"\necho \"# Test API health:\"\necho \"curl -k \\\"https://rqmtmgmt.local/health\\\"\"\necho \"\"\necho \"# List all available API endpoints:\"\necho \"curl -k \\\"https://rqmtmgmt.local/swagger/v1/swagger.json\\\" | jq '.paths | keys[]'\"\n